  for name in self.names:
   row=self.call(['inspect','--type','container',name],False)
   if row['exit_code']==0:self.remove(name)
   else:assert name in row['stderr'] and 'no such' in row['stderr'].lower()
  return {'calls':self.calls,'errors':self.errors,'source_sha256':hashlib.sha256(self.source.encode()).hexdigest(),'all_owned_sandbox_containers_absent':True,'commands':self.commands,'unsafe_outputs_never_executed':True}
